def resolve(path, cwd, links):
    max_links = 8
    links_followed = 0

    if not path.startswith('/'):
        path = cwd + '/' + path

    current = '/'
    remaining = path[1:] if len(path) > 1 else ''

    while remaining or current != '/':
        if not remaining:
            break

        parts = remaining.split('/', 1)
        component = parts[0]
        remaining = parts[1] if len(parts) > 1 else ''

        if component == '' or component == '.':
            continue
        elif component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
        else:
            if current == '/':
                current = '/' + component
            else:
                current = current + '/' + component

            if current in links:
                links_followed += 1
                if links_followed > max_links:
                    return None

                target = links[current]

                if target.startswith('/'):
                    current = '/'
                    remaining = target[1:] + ('/' + remaining if remaining else '')
                else:
                    parent = current.rsplit('/', 1)[0]
                    if parent == '':
                        parent = '/'
                    current = parent
                    remaining = target + ('/' + remaining if remaining else '')

    return current if current else None

